using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.Rendering;
[Serializable] public class D2Manifest {public D2Material[] materials;}
[Serializable] public class D2Material {public string name,unityName,basePath,specPath,normalPath,alphaMode;public float normalScale,metallicFactor,roughnessFactor,ior,transmission;public bool doubleSided;}
public static class Stage08D2Repair {
 static string Out=>Path.GetFullPath("../../../outputs/Stage08D2");static Camera cam;static List<string> checks=new List<string>();
 public static void Build(){
  EditorSceneManager.OpenScene("Assets/Evaluation/Stage08D1_Visual_Evaluation.unity");var manifest=JsonUtility.FromJson<D2Manifest>(File.ReadAllText("Assets/Stage08D2/Material_Adapter_Manifest.json"));var mats=new Dictionary<string,Material>();
  foreach(var x in manifest.materials){foreach(var path in new[]{x.basePath,x.specPath,x.normalPath}.Where(p=>!string.IsNullOrEmpty(p))){var ti=(TextureImporter)AssetImporter.GetAtPath(path);ti.textureCompression=TextureImporterCompression.Uncompressed;ti.sRGBTexture=!path.EndsWith("_Normal.png");if(path.EndsWith("_Normal.png"))ti.textureType=TextureImporterType.NormalMap;ti.SaveAndReimport();}
   var m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.name=x.unityName; m.SetFloat("_WorkflowMode",0);m.EnableKeyword("_SPECULAR_SETUP");m.SetColor("_BaseColor",Color.white);m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(x.basePath));m.SetColor("_SpecColor",Color.white);m.SetTexture("_SpecGlossMap",AssetDatabase.LoadAssetAtPath<Texture2D>(x.specPath));m.SetFloat("_Smoothness",1);m.EnableKeyword("_METALLICSPECGLOSSMAP");m.SetFloat("_Cull",x.doubleSided?0:2);m.SetFloat("_Metallic",x.metallicFactor);
   if(!string.IsNullOrEmpty(x.normalPath)){m.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(x.normalPath));m.SetFloat("_BumpScale",x.normalScale);m.EnableKeyword("_NORMALMAP");}
   // All seven source alpha modes are OPAQUE. Retain those modes and alpha; transmission cannot be replicated by Lit without approximating transparency.
   if(x.alphaMode!="OPAQUE")throw new Exception("Unhandled source alpha mode");m.SetFloat("_Surface",0);m.SetFloat("_ZWrite",1);m.renderQueue=2000;m.SetOverrideTag("RenderType","Opaque");
   var materialPath="Assets/Stage08D2/Materials/"+x.unityName+".mat";var existing=AssetDatabase.LoadAssetAtPath<Material>(materialPath);if(existing==null)AssetDatabase.CreateAsset(m,materialPath);else {EditorUtility.CopySerialized(m,existing);m=existing;}mats.Add(x.name,m);checks.Add($"Adapted {x.name}: IOR {x.ior}, metallic {x.metallicFactor}, roughness {x.roughnessFactor}, alpha {x.alphaMode}, transmission {x.transmission}");
  }
  var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var old=scene.GetRootGameObjects().First(g=>g.name.StartsWith("Approved Robotic"));cam=UnityEngine.Object.FindFirstObjectByType<Camera>();var b=Bounds(old);
  for(int l=0;l<3;l++)Capture("Before_LOD"+l,old,l,b);
  var sharedOriginals=new Dictionary<string,Material>();var groupObj=new GameObject("Stage08D2 Repaired Robotic Rover");var group=groupObj.AddComponent<LODGroup>();var lods=new LOD[3];
  for(int l=0;l<3;l++){var path="Assets/Stage08D2/Models/Perseverance_RepairedV2_LOD"+l+".glb";var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(prefab==null)throw new Exception("Import missing "+path);var obj=(GameObject)PrefabUtility.InstantiatePrefab(prefab);obj.transform.SetParent(groupObj.transform,false);foreach(var r in obj.GetComponentsInChildren<Renderer>()){var materials=r.sharedMaterials;for(int i=0;i<materials.Length;i++){if(materials[i]==null)throw new Exception("Missing material");if(mats.TryGetValue(materials[i].name,out var adapted))materials[i]=adapted;else if(sharedOriginals.TryGetValue(materials[i].name,out var shared))materials[i]=shared;else sharedOriginals.Add(materials[i].name,materials[i]);}r.sharedMaterials=materials;}
   lods[l]=new LOD(new[]{.5f,.25f,.08f}[l],obj.GetComponentsInChildren<Renderer>());group.SetLODs(lods.Take(l+1).ToArray());long tris=AssetDatabase.LoadAllAssetsAtPath(path).OfType<Mesh>().Sum(m=>Enumerable.Range(0,m.subMeshCount).Sum(s=>(long)m.GetIndexCount(s)/3));checks.Add($"LOD{l}: imported triangles {tris}; renderer count {lods[l].renderers.Length}");
  }
  group.SetLODs(lods);group.RecalculateBounds();var rb=Bounds(groupObj);groupObj.transform.position+=new Vector3(-rb.center.x,-rb.min.y,-rb.center.z);old.SetActive(false);
  for(int l=0;l<3;l++)Capture("After_LOD"+l,groupObj,l,b);
  var reference=scene.GetRootGameObjects().First(o=>o.name.StartsWith("Source Fidelity"));groupObj.SetActive(false);reference.SetActive(true);foreach(var r in reference.GetComponentsInChildren<Renderer>()){var arr=r.sharedMaterials;for(int i=0;i<arr.Length;i++)if(mats.TryGetValue(arr[i].name,out var mapped))arr[i]=mapped;r.sharedMaterials=arr;}Capture("Adapted_Source_Reference",reference,0,b);reference.SetActive(false);groupObj.SetActive(true);
  Capture("After_Rear",groupObj,0,b,true);UnityEngine.Object.DestroyImmediate(old);cam.transform.position=b.center+new Vector3(4,2.4f,-4.5f);cam.transform.LookAt(b.center);
  var materialsUsed=groupObj.GetComponentsInChildren<Renderer>().SelectMany(r=>r.sharedMaterials).Distinct().ToArray();checks.Add("Final distinct rover materials "+materialsUsed.Length);if(materialsUsed.Any(m=>m==null||!m.shader.isSupported))throw new Exception("Shader/material check failure");checks.Add("PASS shader support/non-null materials");
  Directory.CreateDirectory("Assets/Stage08D2/Scenes");var pathScene="Assets/Stage08D2/Scenes/Stage08D2_Rover_Fidelity_Evaluation.unity";EditorSceneManager.SaveScene(scene,pathScene);AssetDatabase.SaveAssets();EditorSceneManager.OpenScene(pathScene);var again=UnityEngine.Object.FindObjectsByType<LODGroup>(FindObjectsSortMode.None).First(g=>g.name.StartsWith("Stage08D2"));if(again.GetLODs().Length!=3||again.GetLODs().Any(l=>l.renderers.Any(r=>r==null)))throw new Exception("Reload LOD check");checks.Add("PASS saved scene reload and three LOD reference lists");
  var textures=materialsUsed.SelectMany(m=>m.GetTexturePropertyNames().Select(n=>m.GetTexture(n))).OfType<Texture2D>().Distinct().ToArray();long estimate=0;foreach(var tex in textures){long bytes=(long)tex.width*tex.height*4*4/3;estimate+=bytes;checks.Add($"Texture {tex.name}: {tex.width}x{tex.height} {tex.format}, RGBA32 mip estimate {bytes}");}checks.Add("Shared texture RGBA32+mips estimate bytes "+estimate);File.WriteAllLines(Out+"/Unity_Regression_Checks.txt",checks);Debug.Log("STAGE08D2_BUILD_AND_RELOAD_PASS");
 }
 static Bounds Bounds(GameObject o){var rs=o.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);return b;}
 static void Capture(string name,GameObject obj,int lod,Bounds bounds,bool rear=false){foreach(var g in UnityEngine.Object.FindObjectsByType<LODGroup>(FindObjectsSortMode.None))g.ForceLOD(0);var current=obj.GetComponent<LODGroup>();if(current!=null)current.ForceLOD(lod);cam.transform.position=bounds.center+(rear?new Vector3(-4,2.5f,5):new Vector3(4,2.4f,-4.5f));cam.transform.LookAt(bounds.center);var rt=new RenderTexture(1600,1000,24);cam.targetTexture=rt;for(int i=0;i<3;i++)cam.Render();RenderTexture.active=rt;var t=new Texture2D(1600,1000,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1600,1000),0,0);t.Apply();File.WriteAllBytes(Out+"/Before_After_Screenshots/"+name+".png",t.EncodeToPNG());cam.targetTexture=null;RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(t);UnityEngine.Object.DestroyImmediate(rt);foreach(var g in UnityEngine.Object.FindObjectsByType<LODGroup>(FindObjectsSortMode.None))g.ForceLOD(-1);checks.Add("Captured "+name);}
}
